function setupEventDelegation(container) {
  container.addEventListener("click", (e) => {
    const target = e.target.closest("[data-action]");
    if (!target) return;

    const action = target.dataset.action;
    const id = target.closest("[data-id]")?.dataset.id;

    switch (action) {
      case "add":
        container.dispatchEvent(new CustomEvent("item-add", { detail: { id } }));
        break;
      case "edit":
        container.dispatchEvent(new CustomEvent("item-edit", { detail: { id } }));
        break;
      case "delete":
        container.dispatchEvent(new CustomEvent("item-delete", { detail: { id } }));
        break;
    }
  });
}

class EventEmitter {
  constructor() {
    this.events = {};
  }

  on(event, callback) {
    if (!this.events[event]) this.events[event] = [];
    this.events[event].push(callback);
    return () => this.off(event, callback);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }

  off(event, callback) {
    if (this.events[event]) {
      this.events[event] = this.events[event].filter(cb => cb !== callback);
    }
  }

  once(event, callback) {
    const wrapper = (data) => {
      callback(data);
      this.off(event, wrapper);
    };
    return this.on(event, wrapper);
  }
}

function setupKeyboardNavigation(element) {
  element.addEventListener("keydown", (e) => {
    const items = element.querySelectorAll("[tabindex]");
    const current = document.activeElement;
    const index = Array.from(items).indexOf(current);

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        items[(index + 1) % items.length]?.focus();
        break;
      case "ArrowUp":
        e.preventDefault();
        items[(index - 1 + items.length) % items.length]?.focus();
        break;
      case "Enter":
        current?.click();
        break;
      case "Escape":
        element.blur();
        break;
    }
  });
}

function setupDragAndDrop(draggable, dropzone) {
  draggable.addEventListener("dragstart", (e) => {
    e.dataTransfer.setData("text/plain", draggable.id);
    draggable.classList.add("dragging");
  });

  draggable.addEventListener("dragend", () => {
    draggable.classList.remove("dragging");
  });

  dropzone.addEventListener("dragover", (e) => {
    e.preventDefault();
    dropzone.classList.add("drag-over");
  });

  dropzone.addEventListener("dragleave", () => {
    dropzone.classList.remove("drag-over");
  });

  dropzone.addEventListener("drop", (e) => {
    e.preventDefault();
    dropzone.classList.remove("drag-over");
    const draggedId = e.dataTransfer.getData("text/plain");
    const dragged = document.getElementById(draggedId);
    if (dragged) dropzone.appendChild(dragged);
  });
}
